package org.agentfrc.lesson;
import edu.wpi.first.wpilibj.simulation.*;
/** Fixed-frame latency hypothesis, not measured PWM/CAN or firmware timing. */
public final class PassiveUnloadRig implements AutoCloseable {
 public final PassiveUnloadController controller;private final PassiveUnloadPlant plant;private final EncoderSim encoder;private final DIOSim nip,exit;private final PWMSim pwm;private PassiveUnloadPlant.Sample last;public final NipExitAssessor assessor;private double time;private boolean assessorArmed;private final double radius;private final int fault;private final double scale;private final int delay;private int tick,applyTick=-1;private PassiveUnloadPlant.NeutralMode requested=PassiveUnloadPlant.NeutralMode.BRAKE,applied=requested,pending=requested;
 public PassiveUnloadRig(PassiveUnloadPlant.Config c,PassiveUnloadPlant.NeutralMode policy,int delay){this(c,policy,delay,0,1);}
 public PassiveUnloadRig(PassiveUnloadPlant.Config c,PassiveUnloadPlant.NeutralMode policy,int delay,int fault,double scale){if(fault<0||fault>3||(scale!=1&&scale!=-1))throw new IllegalArgumentException("Declared sensor faults only");this.fault=fault;this.scale=scale;assessor=new NipExitAssessor(c.rollerZ(),c.radius()+c.rollerRadius());if(delay<0||delay>1)throw new IllegalArgumentException("Declared0/1tick delay");this.delay=delay;plant=new PassiveUnloadPlant(c,-.06,.075,.15);radius=c.radius();controller=new PassiveUnloadController(policy);encoder=EncoderSim.createForChannel(0);nip=new DIOSim(2);exit=new DIOSim(3);pwm=new PWMSim(0);last=plant.sample(0);inject();}
 private void inject(){encoder.setCount((int)Math.round(last.rollerAngle()/(2*Math.PI/2048)*scale));nip.setValue(fault==1||Math.abs(last.x()-.072)>radius);exit.setValue(fault==2||fault!=3&&Math.abs(last.x()+.10)>radius);RoboRioSim.setVInVoltage(last.bus());}
 public PassiveUnloadPlant.Sample step(boolean enabled,boolean unload,int substeps){if(substeps!=200&&substeps!=400)throw new IllegalArgumentException("Refinement domain");controller.periodic(enabled,unload);if(!assessorArmed&&controller.phase()==PassiveUnloadController.Phase.UNLOAD){assessor.arm();assessorArmed=true;}if(controller.phase()==PassiveUnloadController.Phase.FAULT){requested=applied=pending=PassiveUnloadPlant.NeutralMode.BRAKE;applyTick=-1;}else{var next=controller.commandedMode();if(next!=requested){requested=next;pending=next;applyTick=tick+delay;}if(applyTick>=0&&tick>=applyTick){applied=pending;applyTick=-1;}}
 for(int i=0;i<substeps;i++){last=plant.step(pwm.getSpeed(),.02/substeps,applied);time+=.02/substeps;assessor.observe(time,last.x(),last.z(),last.vx(),last.vz());}inject();tick++;return last;}
 public PassiveUnloadPlant.NeutralMode appliedMode(){return applied;}
 @Override public void close(){controller.close();}
}
